<?php require_once 'includes/functions.php';if(me())go('dashboard.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=strtolower(trim($_POST['email']??''));$s=db()->prepare('SELECT user_id,name,email,password_hash,blood_group,location,role FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);unset($u['password_hash']);$_SESSION['user']=$u;go('dashboard.php');}$err='Invalid email or password.';}$title='Login';require 'includes/header.php';?><section class="form"><h1>Login</h1><?php if($err):?><p class="alert error"><?=e($err)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn">Login</button></form><p><a href="register.php">Create an account</a></p></section><?php require 'includes/footer.php';?>